function checkout(){
  const scene=new THREE.Scene();const camera=new THREE.PerspectiveCamera(75,window.innerWidth/window.innerHeight,0.1,1000);const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setSize(window.innerWidth,window.innerHeight);document.body.innerHTML='';document.body.appendChild(renderer.domElement);camera.position.z=6;scene.add(new THREE.AmbientLight(0xffffff,0.9));
  function createFireworks() {
    const particleCount = 5000;
    const particles = new THREE.BufferGeometry();
    const positions = new Float32Array(particleCount * 3);
    const colors = new Float32Array(particleCount * 3);
    const velocities = new Float32Array(particleCount * 3);

    for (let i = 0; i < particleCount; i++) {
        const x = (Math.random() - 0.5) * 20;
        const y = (Math.random() - 0.5) * 20;
        const z = (Math.random() - 0.5) * 20;
        positions.set([x, y, z], i * 3);

        const color = Math.random();
        colors.set([color, color, color], i * 3);

        velocities.set([Math.random() * 0.1 - 0.05, Math.random() * 0.1 + 0.1, Math.random() * 0.1 - 0.05], i * 3);
    }

    particles.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    particles.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    const material = new THREE.PointsMaterial({ size: 0.05, vertexColors: true });
    const points = new THREE.Points(particles, material);
    scene.add(points);

    function animate() {
        requestAnimationFrame(animate);
        const positions = particles.attributes.position.array;
        for (let i = 0; i < particleCount; i++) {
            positions[i * 3] += velocities[i * 3];
            positions[i * 3 + 1] += velocities[i * 3 + 1];
            positions[i * 3 + 2] += velocities[i * 3 + 2];
            if (positions[i * 3 + 1] <= -10) {
                positions[i * 3 + 1] = 10;
            }
        }
        particles.attributes.position.needsUpdate = true;
        renderer.render(scene, camera);
    }
    animate();
}
  function animate(){requestAnimationFrame(animate);renderer.render(scene,camera);}animate();
  setTimeout(()=>window.parent.postMessage('INSTALL_CLICK','*'),3000);
}
